"""Network settings for all Hugging Face Hub traffic of the nightly sync job."""

import logging

import httpx2
from huggingface_hub import HfApi, set_client_factory

# Not re-exported publicly; huggingface_hub's default client installs it to honour offline mode and add request ids.
from huggingface_hub.utils._http import hf_request_event_hook

logger = logging.getLogger("app.network")

HUB_TIMEOUT = httpx2.Timeout(60.0, connect=5.0)
JOB_HEADERS = {"X-Acme-Job": "nightly-sync"}


class _HubClient(httpx2.Client):
    """Client whose timeouts cannot be switched off per request.

    Several HfApi methods (model_info, dataset_info, ...) pass `timeout=None` by default, which httpx2 treats as
    "no timeout at all" instead of "use the client's timeout".
    """

    def build_request(self, *args, **kwargs) -> httpx2.Request:
        if kwargs.get("timeout", httpx2.USE_CLIENT_DEFAULT) is None:
            kwargs["timeout"] = httpx2.USE_CLIENT_DEFAULT
        return super().build_request(*args, **kwargs)


def configure_hub_http(transport=None) -> None:
    """Route every huggingface_hub request through one shared client with our timeouts and job header."""

    def client_factory() -> httpx2.Client:
        # Headers set here are merged with the per-request headers of huggingface_hub (user agent, auth, ...).
        return _HubClient(
            headers=JOB_HEADERS,
            timeout=HUB_TIMEOUT,
            transport=transport,
            event_hooks={"request": [hf_request_event_hook]},
            follow_redirects=True,
        )

    set_client_factory(client_factory)


def current_revision(repo_id: str) -> str | None:
    """Commit sha of the main branch of a model repo, or None when the Hub cannot be reached."""
    try:
        return HfApi().model_info(repo_id, revision="main").sha
    except (httpx2.ConnectError, httpx2.TimeoutException) as err:
        logger.warning("Cannot reach the Hugging Face Hub to get the revision of %s: %s", repo_id, err)
        return None

